```html
<button id="btn">Clicked 0 times</button>
<script>
  let count = 0;
  const btn = document.getElementById("btn");
  btn.addEventListener("click", () => {
    count++;
    btn.textContent = `Clicked ${count} times`;
  });
</script>
```

`addEventListener("click", ...)` runs the function every time the button is clicked, and `textContent` updates the button's text.

```tsx
import { useState } from "react";

export function Counter({ start = 0 }: { start?: number }) {
  const [count, setCount] = useState(start);

  return (
    <div className="counter">
      <p>Count: {count}</p>
      <button onClick={() => setCount((c) => c + 1)}>+1</button>
      <button onClick={() => setCount(start)}>Reset</button>
    </div>
  );
}
```

`useState` stores the number, and calling `setCount` re-renders the component with the new value. Using `(c) => c + 1` is safer than `count + 1` when updates happen quickly. Sky Creator Pro is built with React and TypeScript too.

```js
async function loadData() {
  try {
    const res = await fetch("https://api.example.com/items");
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    console.log(data);
  } catch (err) {
    console.error("Couldn't load data:", err);
  }
}

loadData();
```

`fetch` returns a Promise, `await` waits for it, and `res.json()` turns the response into a JavaScript object. Always check `res.ok`, because fetch doesn't throw on 404 or 500 errors.

This C# script uses a **CharacterController** and Unity's classic Input Manager:

```csharp
using UnityEngine;

[RequireComponent(typeof(CharacterController))]
public class PlayerMovement : MonoBehaviour
{
    public float speed = 6f;
    public float gravity = -20f;
    public float jumpHeight = 1.5f;

    CharacterController controller;
    Vector3 velocity;

    void Start()
    {
        controller = GetComponent<CharacterController>();
    }

    void Update()
    {
        bool grounded = controller.isGrounded;
        if (grounded && velocity.y < 0) velocity.y = -2f;

        Vector3 move = transform.right * Input.GetAxis("Horizontal")
                     + transform.forward * Input.GetAxis("Vertical");
        controller.Move(move * speed * Time.deltaTime);

        if (grounded && Input.GetButtonDown("Jump"))
            velocity.y = Mathf.Sqrt(jumpHeight * -2f * gravity);

        velocity.y += gravity * Time.deltaTime;
        controller.Move(velocity * Time.deltaTime);
    }
}
```

Add it to your player object. If your project uses the **new Input System**, set *Active Input Handling* to **Both** in Project Settings → Player, or switch to Input System actions.

**HealthComponent.h**

```cpp
#pragma once

#include "CoreMinimal.h"
#include "Components/ActorComponent.h"
#include "HealthComponent.generated.h"

DECLARE_DYNAMIC_MULTICAST_DELEGATE(FOnDeath);

UCLASS(ClassGroup=(Custom), meta=(BlueprintSpawnableComponent))
class YOURGAME_API UHealthComponent : public UActorComponent
{
    GENERATED_BODY()

public:
    UHealthComponent();

    UFUNCTION(BlueprintCallable, Category="Health")
    void ApplyDamage(float Amount);

    UPROPERTY(BlueprintAssignable, Category="Health")
    FOnDeath OnDeath;

protected:
    virtual void BeginPlay() override;

    UPROPERTY(EditAnywhere, BlueprintReadOnly, Category="Health")
    float MaxHealth = 100.f;

    UPROPERTY(VisibleAnywhere, BlueprintReadOnly, Category="Health")
    float Health = 0.f;
};
```

**HealthComponent.cpp**

```cpp
#include "HealthComponent.h"

UHealthComponent::UHealthComponent()
{
    PrimaryComponentTick.bCanEverTick = false;
}

void UHealthComponent::BeginPlay()
{
    Super::BeginPlay();
    Health = MaxHealth;
}

void UHealthComponent::ApplyDamage(float Amount)
{
    if (Amount <= 0.f || Health <= 0.f) return;

    Health = FMath::Clamp(Health - Amount, 0.f, MaxHealth);
    if (Health <= 0.f)
    {
        OnDeath.Broadcast();
    }
}
```

Replace `YOURGAME_API` with your project's API macro (your module name in caps plus `_API`). Add the component to any actor, and bind **OnDeath** in Blueprints to play a death animation.

A simple wanted system in C++, a component on the player:

```cpp
// WantedComponent.h (key parts)
UCLASS(meta=(BlueprintSpawnableComponent))
class YOURGAME_API UWantedComponent : public UActorComponent
{
    GENERATED_BODY()
public:
    UFUNCTION(BlueprintCallable) void AddHeat(float Amount);
    UFUNCTION(BlueprintPure) int32 GetStars() const { return Stars; }

protected:
    virtual void TickComponent(float DeltaTime, ELevelTick TickType,
                               FActorComponentTickFunction* ThisTickFunction) override;

    UPROPERTY(EditAnywhere) float HeatPerStar = 100.f;
    UPROPERTY(EditAnywhere) float CooldownPerSecond = 10.f;
    UPROPERTY(VisibleAnywhere) float Heat = 0.f;
    UPROPERTY(VisibleAnywhere) int32 Stars = 0;
    UPROPERTY(VisibleAnywhere) bool bSeenByPolice = false;
};
```

```cpp
// WantedComponent.cpp (key parts)
void UWantedComponent::AddHeat(float Amount)
{
    Heat = FMath::Clamp(Heat + Amount, 0.f, HeatPerStar * 5.f);
    Stars = FMath::Clamp(FMath::CeilToInt(Heat / HeatPerStar), 0, 5);
}

void UWantedComponent::TickComponent(float DeltaTime, ELevelTick TickType,
                                     FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
    if (!bSeenByPolice && Heat > 0.f)
    {
        AddHeat(-CooldownPerSecond * DeltaTime); // lose heat while hidden
    }
}
```

Call `AddHeat` when the player commits crimes, set `bSeenByPolice` from your police AI's perception, and spawn more cruisers as `Stars` goes up, from 1 to 5 like Sky Theft. Turn on ticking in the constructor with `PrimaryComponentTick.bCanEverTick = true;`.

In Unreal, `LNK2019` usually means you're using a class from an engine **module** that your game module doesn't link to. For example, using UMG widgets needs the **UMG** module. Fix it in your `YourGame.Build.cs`:

```csharp
PublicDependencyModuleNames.AddRange(new string[] {
    "Core", "CoreUObject", "Engine", "InputCore",
    "EnhancedInput", "UMG", "ChaosVehicles"
});
```

Add only the modules you actually use, then regenerate project files and rebuild. Other causes: a function declared in the .h but never defined in the .cpp, or a missing `YOURGAME_API` on a class used from another module.

A **for loop** repeats code for each item in a list or range.

```python
for i in range(3):
    print("Round", i)
# Round 0, Round 1, Round 2

guns = ["Pistol", "AK-47", "Shotgun"]
for gun in guns:
    print("You have a", gun)
```

The same idea in JavaScript:

```js
for (const gun of ["Pistol", "AK-47", "Shotgun"]) {
  console.log("You have a", gun);
}
```
